import * as TE from "fp-ts/TaskEither";
import { pipe } from "fp-ts/function";

const report = (id: UserID): TE.TaskEither<ApiError, Report> =>
  pipe(
    findUser(id),                      // TaskEither<ApiError, User>
    TE.chain(user => ordersOf(user)),  // bind: Left short-circuits
    TE.map(summarize),
  );
